#include "cmugongdialog.hpp"
namespace mxh::ui{static bool valid(MugongEntry x){return x.id!=0&&!x.name.empty();}bool cMugongDialog::SetSlot(std::size_t s,MugongEntry e){if(s>=kSlots||!valid(e))return false;m_slots[s]=std::move(e);return true;}bool cMugongDialog::ClearSlot(std::size_t s){if(s>=kSlots||!valid(m_slots[s]))return false;m_slots[s]={};if(m_selected==s)m_selected=static_cast<std::size_t>(-1);return true;}bool cMugongDialog::SetEnabled(std::size_t s,bool e){if(s>=kSlots||!valid(m_slots[s]))return false;m_slots[s].enabled=e;return true;}bool cMugongDialog::Select(std::size_t s)noexcept{if(s>=kSlots||!valid(m_slots[s]))return false;m_selected=s;return true;}const MugongEntry* cMugongDialog::Selected()const noexcept{return m_selected<kSlots&&valid(m_slots[m_selected])?&m_slots[m_selected]:nullptr;}}
